fn solve(a: i8, b: i8, c: i8) -> i8 {
    let mut nums = [a, b, c];
    nums.sort_unstable();

    let [x, y, z] = nums;

    // If all equal, no operations needed
    if x == y && y == z {
        return 0;
    }

    // Try to reach a common target value
    // Since operations can increase numbers, the target must be >= max(x, y, z)
    // We'll try targets from z up to z + 4 (because beyond that, operations increase unnecessarily)
    let mut min_ops = i8::MAX;

    for target in z..=z + 4 {
        let mut ops = 0;
        let mut remaining = [target - x, target - y, target - z];

        // All differences must be non-negative
        if remaining.iter().any(|&diff| diff < 0) {
            continue;
        }

        // Pair as many +1/+1 operations as possible
        for diff in remaining.iter_mut() {
            // Use +2 operations for odd differences first
            if *diff % 2 == 1 {
                ops += 1;
                *diff -= 1;
            }
        }

        // Now all diffs are even
        let total_even_diff: i8 = remaining.iter().sum();
        ops += total_even_diff / 2;

        // Check if this ops count is achievable
        // Each +2 operation handles 2 units, each +1/+1 handles 2 units total
        // So total units to cover must be even? Let's verify:
        // Actually, total increase = sum(remaining). Each +2 covers 2 units.
        // Each +1/+1 covers 2 units total. So total units must be even.
        // But we already made all diffs even, so sum is even.
        // Also, we need enough "slots" for +1/+1 ops: they require two numbers.
        // We can always arrange because we have three numbers.

        min_ops = min_ops.min(ops);
    }

    min_ops
}